package sarvam

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
)

type Agent struct {
	LookPath func(string) (string, error)
}

func New() *Agent {
	return &Agent{LookPath: exec.LookPath}
}

func (a *Agent) Info() protocol.InfoResponse {
	hookNames := make([]string, 0, len(hookSpecs))
	for _, spec := range hookSpecs {
		hookNames = append(hookNames, spec.HookName)
	}
	return protocol.InfoResponse{
		ProtocolVersion: protocol.ProtocolVersion,
		Name:            AgentName,
		Type:            AgentType,
		Description:     "Sarvam Code external agent integration for Entire",
		IsPreview:       true,
		ProtectedDirs:   []string{".sarvam"},
		HookNames:       hookNames,
		Capabilities: protocol.DeclaredCapabilities{
			Hooks:              true,
			TranscriptAnalyzer: true,
			CompactTranscript:  true,
			TokenCalculator:    true,
			UsesTerminal:       true,
		},
	}
}

func (a *Agent) Detect() protocol.DetectResponse {
	lookPath := a.LookPath
	if lookPath == nil {
		lookPath = exec.LookPath
	}
	if _, err := lookPath(sarvamBinary); err == nil {
		return protocol.DetectResponse{Present: true}
	}
	// The CLI itself is enough: sessions and transcripts live under
	// SARVAM_HOME even when the binary is temporarily off PATH.
	if stat, err := os.Stat(sarvamHome()); err == nil && stat.IsDir() {
		return protocol.DetectResponse{Present: true}
	}
	return protocol.DetectResponse{Present: false}
}

func (a *Agent) GetSessionID(input *protocol.HookInputJSON) string {
	if input != nil && strings.TrimSpace(input.SessionID) != "" {
		return input.SessionID
	}
	return stubSessionID
}

// sarvamHome resolves $SARVAM_HOME, defaulting to ~/.sarvam.
func sarvamHome() string {
	if v := os.Getenv("SARVAM_HOME"); v != "" {
		return v
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ".sarvam"
	}
	return filepath.Join(home, ".sarvam")
}

// GetSessionDir returns the root of sarvam's session store. Sessions are
// global, not repo-scoped: one JSONL per run under sessions/YYYY/MM/DD/.
func (a *Agent) GetSessionDir(repoPath string) (string, error) {
	_ = repoPath // kept for interface symmetry; the store is global
	return filepath.Join(sarvamHome(), "sessions"), nil
}

// ResolveSessionFile maps a session ID to its native rollout JSONL when one
// exists, and to a deterministic in-store path otherwise. The fallback keeps
// read/write-session round-trips stable without ever touching a native
// transcript that exists on disk.
func (a *Agent) ResolveSessionFile(sessionDir, sessionID string) string {
	if strings.TrimSpace(sessionDir) == "" {
		sessionDir, _ = a.GetSessionDir("")
	}
	if id := strings.TrimSpace(sessionID); id != "" {
		if path := findRolloutFile(sessionDir, id); path != "" {
			return path
		}
	}
	return filepath.Join(sessionDir, safeFilename(sessionID)+".jsonl")
}

// findRolloutFile searches the YYYY/MM/DD tree for the rollout file whose
// name ends with the thread ID, returning the newest match.
func findRolloutFile(sessionDir, sessionID string) string {
	safe := safeFilename(sessionID)
	if safe == "" || safe == stubSessionID {
		return ""
	}
	pattern := filepath.Join(sessionDir, "*", "*", "*", "rollout-*-"+safe+".jsonl")
	matches, err := filepath.Glob(pattern)
	if err != nil || len(matches) == 0 {
		return ""
	}
	sort.Strings(matches) // date-prefixed names sort chronologically
	return matches[len(matches)-1]
}

func (a *Agent) FormatResumeCommand(sessionID string) string {
	if strings.TrimSpace(sessionID) == "" {
		return "sarvam-code resume --last"
	}
	return "sarvam-code resume " + shellQuote(sessionID)
}

func shellQuote(value string) string {
	if value == "" {
		return "''"
	}
	if strings.IndexFunc(value, func(r rune) bool {
		return !isSafeShellQuoteRune(r)
	}) == -1 {
		return value
	}
	return "'" + strings.ReplaceAll(value, "'", "'\\''") + "'"
}

func isSafeShellQuoteRune(r rune) bool {
	return r == '-' || r == '_' || r == '.' || r == ':' ||
		(r >= '0' && r <= '9') ||
		(r >= 'a' && r <= 'z') ||
		(r >= 'A' && r <= 'Z')
}

// safeFilename maps a session ID onto a filename-safe string. Session IDs are
// UUIDs in practice, but the protocol accepts any string, so anything hostile
// collapses to a hash instead of reaching the filesystem.
func safeFilename(sessionID string) string {
	original := strings.TrimSpace(sessionID)
	if original == "" {
		return stubSessionID
	}
	var b strings.Builder
	for _, r := range original {
		switch {
		case r >= '0' && r <= '9', r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z':
			b.WriteRune(r)
		default:
			b.WriteByte('_')
		}
	}
	out := strings.Trim(b.String(), "._")
	if out == "" {
		return stubSessionID
	}
	if out == original {
		return out
	}
	sum := sha256.Sum256([]byte(original))
	return fmt.Sprintf("~%x", sum[:16])
}

// sessionIDAndRef picks the session reference for a read: an explicit ref
// wins, then the native rollout for the ID, then the deterministic path.
func (a *Agent) sessionIDAndRef(input *protocol.HookInputJSON) (string, string) {
	sessionID := stubSessionID
	if input != nil && strings.TrimSpace(input.SessionID) != "" {
		sessionID = input.SessionID
	}
	if input != nil && strings.TrimSpace(input.SessionRef) != "" {
		return sessionID, input.SessionRef
	}
	return sessionID, a.ResolveSessionFile("", sessionID)
}

// ReadSession rebuilds the AgentSession envelope from the transcript at the
// session ref. Native data is the raw rollout JSONL; modified files are
// derived from it on the fly.
func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
	sessionID, sessionRef := a.sessionIDAndRef(input)
	data, err := os.ReadFile(sessionRef)
	if errors.Is(err, os.ErrNotExist) {
		data = nil
	} else if err != nil {
		return protocol.AgentSessionJSON{}, err
	}
	modifiedFiles, _, err := a.ExtractModifiedFiles(sessionRef, 0)
	if errors.Is(err, os.ErrNotExist) {
		modifiedFiles = nil
	} else if err != nil {
		return protocol.AgentSessionJSON{}, err
	}
	return protocol.AgentSessionJSON{
		SessionID:     sessionID,
		AgentName:     AgentName,
		RepoPath:      protocol.RepoRoot(),
		SessionRef:    sessionRef,
		StartTime:     time.Now().UTC().Format(time.RFC3339),
		NativeData:    data,
		ModifiedFiles: modifiedFiles,
		NewFiles:      []string{},
		DeletedFiles:  []string{},
	}, nil
}

// WriteSession persists native session bytes at the ref Entire resolved. The
// native rollout for the ID is never a write target: ResolveSessionFile only
// returns it when it already exists, and Entire passes the ref it asked us to
// resolve, which for capture flows is the deterministic store path.
func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
	ref := strings.TrimSpace(session.SessionRef)
	if ref == "" {
		if strings.TrimSpace(session.SessionID) == "" {
			return errMissingSessionRef
		}
		ref = a.ResolveSessionFile("", session.SessionID)
	}
	if err := os.MkdirAll(filepath.Dir(ref), 0o700); err != nil {
		return err
	}
	return os.WriteFile(ref, session.NativeData, 0o600)
}

// ReadTranscript returns the raw transcript bytes at the ref. Entire runs its
// own redaction over the result and hands a temp copy back through
// compact-transcript for the Entire-facing projection.
func (a *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
	return os.ReadFile(sessionRef)
}

func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
	if maxSize <= 0 {
		return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
	}
	if len(content) == 0 {
		return [][]byte{[]byte{}}, nil
	}
	var chunks [][]byte
	for start := 0; start < len(content); start += maxSize {
		end := start + maxSize
		if end > len(content) {
			end = len(content)
		}
		chunk := make([]byte, end-start)
		copy(chunk, content[start:end])
		chunks = append(chunks, chunk)
	}
	return chunks, nil
}

func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	total := 0
	for _, chunk := range chunks {
		total += len(chunk)
	}
	out := make([]byte, 0, total)
	for _, chunk := range chunks {
		out = append(out, chunk...)
	}
	return out, nil
}

package sarvam

import (
	"bytes"
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
)

// ParseHook converts a sarvam lifecycle hook payload into a protocol event.
//
// Two input shapes reach this code path:
//
//   - the native payload sarvam pipes to the installed command (identified by
//     its "hook_event_name" field), forwarded verbatim by Entire, and
//   - the protocol HookInputJSON the compliance harness (and legacy callers)
//     send, identified by "hook_type".
//
// Events with no protocol representation return a nil event; the handler
// prints "null" and Entire treats them as non-lifecycle.
func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
	trimmed := bytes.TrimSpace(input)
	if len(trimmed) == 0 {
		return nil, nil
	}

	var native sarvamHookInput
	if err := json.Unmarshal(trimmed, &native); err != nil {
		return nil, fmt.Errorf("parse sarvam hook input: %w", err)
	}

	if strings.TrimSpace(native.HookEventName) == "" {
		// Protocol-shaped input: map it onto the native structure so both
		// shapes flow through one path.
		var hookInput protocol.HookInputJSON
		if err := json.Unmarshal(trimmed, &hookInput); err != nil {
			return nil, fmt.Errorf("parse hook input: %w", err)
		}
		native.HookEventName = hookInput.HookType
		if native.HookEventName == "" {
			native.HookEventName = hookName
		}
		native.SessionID = hookInput.SessionID
		native.TranscriptPath = hookInput.SessionRef
		native.Prompt = hookInput.UserPrompt
		native.ToolName = hookInput.ToolName
		native.ToolUseID = hookInput.ToolUseID
		native.ToolInput = hookInput.ToolInput
	}

	event := sarvamEventName(native.HookEventName, hookName)
	metadata := hookMetadata(native)

	switch event {
	case "SessionStart":
		return &protocol.EventJSON{
			Type:       1,
			SessionID:  a.sessionID(native),
			SessionRef: a.sessionRef(native),
			Model:      native.Model,
			Timestamp:  timestampNow(),
			Metadata:   metadata,
		}, nil
	case "UserPromptSubmit":
		if strings.TrimSpace(native.Prompt) == "" {
			return nil, nil
		}
		return &protocol.EventJSON{
			Type:       2,
			SessionID:  a.sessionID(native),
			SessionRef: a.sessionRef(native),
			Prompt:     native.Prompt,
			Model:      native.Model,
			Timestamp:  timestampNow(),
			Metadata:   metadata,
		}, nil
	case "Stop":
		return &protocol.EventJSON{
			Type:            3,
			SessionID:       a.sessionID(native),
			SessionRef:      a.sessionRef(native),
			Model:           native.Model,
			Timestamp:       timestampNow(),
			ResponseMessage: native.LastAssistantMessage,
			Metadata:        metadata,
		}, nil
	case "PreCompact", "PostCompact":
		return &protocol.EventJSON{
			Type:       4,
			SessionID:  a.sessionID(native),
			SessionRef: a.sessionRef(native),
			Model:      native.Model,
			Timestamp:  timestampNow(),
			Metadata:   metadata,
		}, nil
	default:
		// PreToolUse, PostToolUse, PermissionRequest, and anything unknown:
		// no lifecycle significance for Entire.
		return nil, nil
	}
}

func (a *Agent) sessionID(native sarvamHookInput) string {
	if id := strings.TrimSpace(native.SessionID); id != "" {
		return id
	}
	return stubSessionID
}

func (a *Agent) sessionRef(native sarvamHookInput) string {
	if path := strings.TrimSpace(native.TranscriptPath); path != "" {
		return path
	}
	return a.ResolveSessionFile("", native.SessionID)
}

func timestampNow() string {
	return time.Now().UTC().Format(time.RFC3339)
}

// sarvamEventName resolves the native event from the payload, falling back to
// the hook name Entire passed. Both kebab-case protocol names and PascalCase
// native names are accepted.
func sarvamEventName(fromPayload, fromFlag string) string {
	if name := strings.TrimSpace(fromPayload); name != "" {
		return name
	}
	for _, spec := range hookSpecs {
		if fromFlag == spec.HookName {
			return spec.SarvamEvent
		}
	}
	return fromFlag
}

func hookMetadata(native sarvamHookInput) map[string]string {
	metadata := map[string]string{
		"agent":            AgentName,
		"hook_event_name":  native.HookEventName,
	}
	if native.CWD != "" {
		metadata["cwd"] = native.CWD
	}
	if native.Source != "" {
		metadata["source"] = native.Source
	}
	if native.Trigger != "" {
		metadata["trigger"] = native.Trigger
	}
	if native.PermissionMode != "" {
		metadata["permission_mode"] = native.PermissionMode
	}
	if native.TurnID != "" {
		metadata["turn_id"] = native.TurnID
	}
	return metadata
}

// hookCommand renders the command written into .sarvam/config.toml. It names
// the binary as plain `entire` so it resolves through PATH when the hook
// runs; baking in an absolute path would put a machine-specific path into a
// repo-local config that is routinely committed.
func hookCommand(hookName string) string {
	return fmt.Sprintf("sh -c 'if command -v entire >/dev/null 2>&1; then entire hooks %s %s >/dev/null 2>&1 || true; fi'", AgentName, hookName)
}

// projectConfigPath is the repo-local sarvam config that carries hook
// declarations. Hook *state* (trust) lives in the user config and stays
// untouched: grant it through the sarvam TUI's /hooks review, never here.
func projectConfigPath() string {
	return filepath.Join(protocol.RepoRoot(), ".sarvam", "config.toml")
}

func (a *Agent) InstallHooks(localDev bool, force bool) (int, error) {
	_ = localDev // hook state is user-managed; there is no dev path to point at
	path := projectConfigPath()
	entries := make([]configHookEntry, 0, len(hookSpecs))
	for _, spec := range hookSpecs {
		entries = append(entries, configHookEntry{
			Event:  spec.SarvamEvent,
			Name:   spec.EntryName,
			Command: hookCommand(spec.HookName),
		})
	}
	return upsertHookEntries(path, entries, force)
}

func (a *Agent) UninstallHooks() error {
	return removeHookEntries(projectConfigPath(), hookSpecs)
}

func (a *Agent) AreHooksInstalled() bool {
	path := projectConfigPath()
	for _, spec := range hookSpecs {
		if !hookEntryInstalled(path, spec.SarvamEvent, spec.EntryName, hookCommand(spec.HookName)) {
			return false
		}
	}
	return true
}

package sarvam

import (
	"fmt"
	"os"
	"strings"
)

// Sarvam's project config is hand-authored TOML that can carry anything, so
// hook install/uninstall edits it as lines rather than round-tripping a TOML
// parser: every line we do not own is preserved byte-for-byte. Only the
// narrow grammar of hook declarations is understood:
//
//	[[hooks.<Event>]]            matcher group (body: optional matcher keys)
//	[[hooks.<Event>.hooks]]      hook entry (body: type/command/timeout/...)
//
// Entire-owned entries are recognized by their command carrying the
// "entire hooks <agent>" marker, the same convention the other external
// agents use.

const entireCommandMarker = "entire hooks " + AgentName

// configHookEntry is one hook handler we manage in the project config.
type configHookEntry struct {
	Event   string // PascalCase sarvam event key
	Name    string // stable logical name (used only for matching our entries)
	Command string // exact command string
}

type tomlBlock struct {
	header string   // raw header line, "" for the preamble block
	body   []string // lines after the header until the next header
}

func isHeaderLine(line string) bool {
	return strings.HasPrefix(line, "[")
}

func headerEvent(header string) (event string, kind string) {
	trimmed := strings.TrimSpace(header)
	for _, prefix := range []string{"[[hooks.", "[hooks."} {
		if strings.HasPrefix(trimmed, prefix) {
			rest := strings.TrimSuffix(strings.TrimPrefix(trimmed, prefix), "]")
			rest = strings.TrimSuffix(rest, "]")
			switch {
			case strings.HasSuffix(rest, ".hooks"):
				return strings.TrimSuffix(rest, ".hooks"), "hooks"
			default:
				return rest, "group"
			}
		}
	}
	return "", ""
}

// parseConfigBlocks splits the file into header-anchored blocks. The first
// block (preamble) has an empty header and holds everything before the first
// table header.
func parseConfigBlocks(content string) []tomlBlock {
	lines := strings.Split(content, "\n")
	// A trailing newline produces one empty final element; remember it so
	// serialization round-trips.
	trailingNewline := len(lines) > 0 && lines[len(lines)-1] == ""
	if trailingNewline {
		lines = lines[:len(lines)-1]
	}
	blocks := []tomlBlock{{}}
	for _, line := range lines {
		if isHeaderLine(strings.TrimSpace(line)) {
			blocks = append(blocks, tomlBlock{header: strings.TrimSpace(line)})
			continue
		}
		blocks[len(blocks)-1].body = append(blocks[len(blocks)-1].body, line)
	}
	return blocks
}

func serializeConfigBlocks(blocks []tomlBlock) string {
	var b strings.Builder
	for i, block := range blocks {
		if i > 0 {
			b.WriteByte('\n')
		}
		if block.header != "" {
			b.WriteString(block.header)
			b.WriteByte('\n')
		}
		for _, line := range block.body {
			b.WriteString(line)
			b.WriteByte('\n')
		}
	}
	return b.String()
}

// entryCommand returns the command value of a hook-entry block, or "".
func entryCommand(block tomlBlock) string {
	for _, line := range block.body {
		key, value, ok := parseKeyValue(line)
		if ok && key == "command" {
			return value
		}
	}
	return ""
}

func entryIsCommandType(block tomlBlock) bool {
	for _, line := range block.body {
		key, value, ok := parseKeyValue(line)
		if ok && key == "type" && value == "command" {
			return true
		}
	}
	return false
}

// isEntireEntry reports whether a hook-entry block belongs to this adapter.
func isEntireEntry(block tomlBlock) bool {
	if !entryIsCommandType(block) {
		return false
	}
	command := entryCommand(block)
	return command != "" && strings.Contains(command, entireCommandMarker)
}

// parseKeyValue parses a single `key = value` TOML line, decoding basic and
// literal strings. Booleans and numbers come back raw.
func parseKeyValue(line string) (key string, value string, ok bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "#") {
		return "", "", false
	}
	eq := strings.Index(trimmed, "=")
	if eq < 0 {
		return "", "", false
	}
	key = strings.TrimSpace(trimmed[:eq])
	value = strings.TrimSpace(trimmed[eq+1:])
	if len(value) >= 2 {
		if value[0] == '"' && value[len(value)-1] == '"' {
			return key, unescapeBasicString(value[1 : len(value)-1]), true
		}
		if value[0] == '\'' && value[len(value)-1] == '\'' {
			return key, value[1 : len(value)-1], true
		}
	}
	return key, value, true
}

func unescapeBasicString(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			default:
				b.WriteByte(s[i])
			}
			continue
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// encodeTOMLString renders s as a TOML basic string.
func encodeTOMLString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\t':
			b.WriteString("\\t")
		case '\r':
			b.WriteString("\\r")
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func newEntryBlocks(event, command string) []tomlBlock {
	return []tomlBlock{
		{header: fmt.Sprintf("[[hooks.%s]]", event)},
		{header: fmt.Sprintf("[[hooks.%s.hooks]]", event), body: []string{
			"type = \"command\"",
			fmt.Sprintf("command = %s", encodeTOMLString(command)),
		}},
	}
}

// repairParentlessHooks inserts the missing [[hooks.<Event>]] group headers
// the sarvam docs' example leads users to omit: without them the whole hooks
// table fails to parse ("invalid type: map, expected a sequence") and the CLI
// silently drops every hook. Inserting the header turns the map into the
// array of one matcher group, keeping the author's entries.
func repairParentlessHooks(blocks []tomlBlock) []tomlBlock {
	out := make([]tomlBlock, 0, len(blocks)+len(hookSpecs))
	seenGroup := map[string]bool{}
	for _, block := range blocks {
		event, kind := headerEvent(block.header)
		if event != "" && kind == "hooks" && !seenGroup[event] {
			if isManagedEvent(event) {
				out = append(out, tomlBlock{header: fmt.Sprintf("[[hooks.%s]]", event)})
			}
		}
		if event != "" && kind == "group" {
			seenGroup[event] = true
		}
		out = append(out, block)
	}
	return out
}

func isManagedEvent(event string) bool {
	for _, spec := range hookSpecs {
		if spec.SarvamEvent == event {
			return true
		}
	}
	return false
}

// checkNoMapFormEvents rejects the single-bracket map form for events we
// manage. Appending an array-of-tables next to a table definition is a TOML
// type conflict; failing loudly beats corrupting a config the user must fix
// by hand anyway.
func checkNoMapFormEvents(blocks []tomlBlock) error {
	for _, block := range blocks {
		event, kind := headerEvent(block.header)
		if event != "" && kind == "group" && isManagedEvent(event) && !strings.HasPrefix(block.header, "[[") {
			return fmt.Errorf(".sarvam/config.toml defines [hooks.%s] as a table; the sarvam CLI requires an array of matcher groups — replace the header with [[hooks.%s]] and rerun", event, event)
		}
	}
	return nil
}

// upsertHookEntries installs the given entries, returning how many hook
// handlers were added or updated. Unrelated config content is untouched.
func upsertHookEntries(path string, entries []configHookEntry, force bool) (int, error) {
	blocks, err := loadBlocks(path)
	if err != nil {
		return 0, err
	}
	if err := checkNoMapFormEvents(blocks); err != nil {
		return 0, err
	}
	if force {
		blocks = dropEntireEntries(blocks)
	}
	blocks = repairParentlessHooks(blocks)

	count := 0
	for _, entry := range entries {
		changed, err := upsertOne(&blocks, entry)
		if err != nil {
			return 0, err
		}
		if changed {
			count++
		}
	}
	if count == 0 {
		return 0, nil
	}
	if err := saveBlocks(path, blocks); err != nil {
		return 0, err
	}
	return count, nil
}

func upsertOne(blocks *[]tomlBlock, entry configHookEntry) (bool, error) {
	// Update in place when an owned entry exists.
	for i, block := range *blocks {
		event, kind := headerEvent(block.header)
		if event != entry.Event || kind != "hooks" {
			continue
		}
		if !isEntireEntry(block) {
			continue
		}
		if entryCommand(block) == entry.Command {
			return false, nil
		}
		for j, line := range block.body {
			if key, _, ok := parseKeyValue(line); ok && key == "command" {
				(*blocks)[i].body[j] = fmt.Sprintf("command = %s", encodeTOMLString(entry.Command))
				return true, nil
			}
		}
	}

	// Insert after the event's last hook entry when one exists; otherwise
	// open a fresh group at the end of the hooks region (or EOF).
	insertAt := -1
	lastHooksRegion := -1
	for i, block := range *blocks {
		event, kind := headerEvent(block.header)
		if event == "" {
			continue
		}
		if kind == "hooks" && event == entry.Event {
			insertAt = i + 1
		}
		if strings.HasPrefix(block.header, "[hooks.") || strings.HasPrefix(block.header, "[[hooks.") {
			lastHooksRegion = i + 1
		}
	}
	at := len(*blocks)
	if insertAt >= 0 {
		at = insertAt
	} else if lastHooksRegion >= 0 {
		at = lastHooksRegion
	}
	newBlocks := newEntryBlocks(entry.Event, entry.Command)
	out := make([]tomlBlock, 0, len(*blocks)+len(newBlocks))
	out = append(out, (*blocks)[:at]...)
	out = append(out, newBlocks...)
	out = append(out, (*blocks)[at:]...)
	*blocks = out
	return true, nil
}

// removeHookEntries deletes every entry this adapter owns.
func removeHookEntries(path string, specs []hookSpec) error {
	blocks, err := loadBlocks(path)
	if err != nil {
		return err
	}
	if len(blocks) == 1 && len(blocks[0].body) == 0 && blocks[0].header == "" {
		return nil // no config at all
	}
	kept := dropEntireEntries(blocks)
	kept = dropEmptyManagedGroups(kept)
	return saveBlocks(path, kept)
}

func dropEntireEntries(blocks []tomlBlock) []tomlBlock {
	out := make([]tomlBlock, 0, len(blocks))
	for _, block := range blocks {
		event, kind := headerEvent(block.header)
		if event != "" && kind == "hooks" && isEntireEntry(block) {
			continue
		}
		out = append(out, block)
	}
	return out
}

// dropEmptyManagedGroups removes [[hooks.<Event>]] group headers for our
// events whose body is empty after entry removal. Groups with content and any
// other table are kept.
func dropEmptyManagedGroups(blocks []tomlBlock) []tomlBlock {
	out := make([]tomlBlock, 0, len(blocks))
	for _, block := range blocks {
		event, kind := headerEvent(block.header)
		if event != "" && kind == "group" && isManagedEvent(event) && len(block.body) == 0 {
			continue
		}
		out = append(out, block)
	}
	return out
}

func hookEntryInstalled(path, event, name, command string) bool {
	blocks, err := loadBlocks(path)
	if err != nil {
		return false
	}
	blocks = repairParentlessHooks(blocks)
	for _, block := range blocks {
		e, kind := headerEvent(block.header)
		if e != event || kind != "hooks" {
			continue
		}
		if isEntireEntry(block) && entryCommand(block) == command {
			return true
		}
	}
	return false
}

func loadBlocks(path string) ([]tomlBlock, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return []tomlBlock{{}}, nil
	}
	if err != nil {
		return nil, err
	}
	if len(strings.TrimSpace(string(data))) == 0 {
		return []tomlBlock{{}}, nil
	}
	return parseConfigBlocks(string(data)), nil
}

func saveBlocks(path string, blocks []tomlBlock) error {
	content := serializeConfigBlocks(blocks)
	if err := os.MkdirAll(mustDir(path), 0o755); err != nil {
		return err
	}
	mode := os.FileMode(0o600)
	if existing, err := os.Stat(path); err == nil {
		mode = existing.Mode().Perm()
	}
	return os.WriteFile(path, []byte(content), mode)
}

func mustDir(path string) string {
	idx := strings.LastIndex(path, "/")
	if idx < 0 {
		return "."
	}
	return path[:idx]
}

package sarvam

import (
	"bufio"
	"encoding/json"
	"errors"
	"os"
	"sort"
	"strings"
)

// The rollout JSONL is append-only, and Entire tracks progress with the
// (position, offset) pair this analyzer produces, so offsets are record
// indexes: get-transcript-position returns the number of physical lines, and
// extract --offset is the line index to resume from.

// maxRolloutLine bounds a single rollout record. One record can embed a whole
// tool output, so the 10 MB ceiling the other JSONL scanners use applies.
const maxRolloutLine = 10 * 1024 * 1024

// readRolloutLines parses the rollout JSONL. Unparseable lines become empty
// placeholders so line offsets stay aligned with the physical file even when
// a record is torn mid-write.
func readRolloutLines(path string) ([]rolloutLine, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()

	var lines []rolloutLine
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024), maxRolloutLine)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		var record rolloutLine
		if json.Unmarshal([]byte(line), &record) != nil {
			record = rolloutLine{}
		}
		lines = append(lines, record)
	}
	return lines, scanner.Err()
}

func (a *Agent) GetTranscriptPosition(path string) (int, error) {
	lines, err := readRolloutLines(path)
	if errors.Is(err, os.ErrNotExist) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	return len(lines), nil
}

func clampOffset(offset, length int) int {
	if offset < 0 {
		return 0
	}
	if offset > length {
		return length
	}
	return offset
}

func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
	lines, err := readRolloutLines(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, 0, nil
	}
	if err != nil {
		return nil, 0, err
	}
	start := clampOffset(offset, len(lines))

	seen := map[string]struct{}{}
	for _, line := range lines[start:] {
		if line.Type != "response_item" {
			continue
		}
		var call rolloutFunctionCall
		if json.Unmarshal(line.Payload, &call) != nil || call.Type != "function_call" {
			continue
		}
		for _, file := range pathsFromToolCall(call) {
			normalized := strings.TrimSpace(file)
			if normalized != "" {
				seen[normalized] = struct{}{}
			}
		}
	}
	files := make([]string, 0, len(seen))
	for file := range seen {
		files = append(files, file)
	}
	sort.Strings(files)
	return files, len(lines), nil
}

// pathsFromToolCall extracts the file paths a tool call touches.
// write_file/edit_file carry "path"; exec_command carries a shell "command"
// whose redirects are best-effort parsed.
func pathsFromToolCall(call rolloutFunctionCall) []string {
	var args map[string]any
	if json.Unmarshal([]byte(call.Arguments), &args) != nil {
		return nil
	}
	switch call.Name {
	case "write_file":
		return stringField(args, "path")
	case "edit_file", "apply_patch", "edit":
		var paths []string
		paths = append(paths, stringField(args, "path")...)
		paths = append(paths, stringField(args, "file_path")...)
		return paths
	case "exec_command":
		command, _ := args["command"].(string)
		return pathsFromShellCommand(command)
	default:
		// Unknown tools: fall back to common path keys.
		var paths []string
		for _, key := range []string{"path", "file_path", "filePath", "notebook_path"} {
			paths = append(paths, stringField(args, key)...)
		}
		return paths
	}
}

func stringField(args map[string]any, key string) []string {
	value, ok := args[key].(string)
	if !ok || strings.TrimSpace(value) == "" {
		return nil
	}
	return []string{value}
}

func (a *Agent) ExtractPrompts(sessionRef string, offset int) ([]string, error) {
	lines, err := readRolloutLines(sessionRef)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	start := clampOffset(offset, len(lines))

	var prompts []string
	for _, line := range lines[start:] {
		if line.Type != "response_item" {
			continue
		}
		var message rolloutMessage
		if json.Unmarshal(line.Payload, &message) != nil || message.Role != "user" {
			continue
		}
		text := messageText(message, "input_text")
		if text == "" || isHarnessContext(text) {
			continue
		}
		prompts = append(prompts, text)
	}
	return prompts, nil
}

// isHarnessContext filters the leading environment block sarvam records as a
// user item — it is injected context, not a human prompt.
func isHarnessContext(text string) bool {
	return strings.HasPrefix(strings.TrimSpace(text), "<environment_context>")
}

// messageText concatenates the text blocks of the given type.
func messageText(message rolloutMessage, blockType string) string {
	var b strings.Builder
	for _, block := range message.Content {
		if block.Type == blockType && block.Text != "" {
			if b.Len() > 0 {
				b.WriteByte('\n')
			}
			b.WriteString(block.Text)
		}
	}
	return b.String()
}

// ExtractSummary returns the agent's last assistant message as the session
// summary, mirroring the other external agents: it is the natural "what did
// the agent do" line for a checkpoint.
func (a *Agent) ExtractSummary(sessionRef string) (string, bool, error) {
	lines, err := readRolloutLines(sessionRef)
	if errors.Is(err, os.ErrNotExist) {
		return "", false, nil
	}
	if err != nil {
		return "", false, err
	}
	for i := len(lines) - 1; i >= 0; i-- {
		line := lines[i]
		if line.Type != "response_item" {
			continue
		}
		var message rolloutMessage
		if json.Unmarshal(line.Payload, &message) != nil || message.Role != "assistant" {
			continue
		}
		if text := messageText(message, "output_text"); strings.TrimSpace(text) != "" {
			return text, true, nil
		}
	}
	return "", false, nil
}

package sarvam

import (
	"encoding/base64"
	"encoding/json"
	"os"
	"strings"

	"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
)

// CompactTranscript converts a native rollout JSONL into Entire Transcript
// Format. Entire calls this on each checkpoint write with a temp file of the
// already-redacted transcript; without it, Entire's generic JSONL compactor
// drops sarvam's `response_item` records because they carry no top-level
// role/message shape it recognizes.
//
// Projection (mirrors the wire shapes Entire's compactor reads):
//
//	response_item message/user     -> {"type":"user","message":{...}}
//	response_item message/assistant-> {"type":"assistant","message":{...}}
//	function_call                  -> assistant message with a tool_use block
//	function_call_output           -> user message with a tool_result block
//
// Developer messages (injected harness instructions), reasoning, and the
// event stream are dropped: none of them belong in a checkpoint transcript.
func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
	lines, err := readRolloutLines(sessionRef)
	if err != nil {
		if os.IsNotExist(err) {
			lines = nil
		} else {
			return protocol.CompactTranscriptResponse{}, err
		}
	}

	var out strings.Builder
	for _, line := range lines {
		for _, projected := range projectRolloutLine(line) {
			encoded, err := json.Marshal(projected)
			if err != nil {
				continue
			}
			out.Write(encoded)
			out.WriteByte('\n')
		}
	}

	return protocol.CompactTranscriptResponse{
		Transcript: base64.StdEncoding.EncodeToString([]byte(out.String())),
	}, nil
}

func projectRolloutLine(line rolloutLine) []any {
	if line.Type != "response_item" {
		return nil
	}

	var probe struct {
		Type string `json:"type"`
	}
	if json.Unmarshal(line.Payload, &probe) != nil {
		return nil
	}

	switch probe.Type {
	case "message":
		var message rolloutMessage
		if json.Unmarshal(line.Payload, &message) != nil {
			return nil
		}
		return projectMessage(message)

	case "function_call":
		var call rolloutFunctionCall
		if json.Unmarshal(line.Payload, &call) != nil {
			return nil
		}
		return []any{wireMessage{
			Role: "assistant",
			Content: []any{wireToolUseBlock{
				Type:  "tool_use",
				ID:    call.CallID,
				Name:  call.Name,
				Input: decodeToolArguments(call.Arguments),
			}},
		}}

	case "function_call_output":
		var output rolloutFunctionCallOutput
		if json.Unmarshal(line.Payload, &output) != nil {
			return nil
		}
		return []any{wireMessage{
			Role: "user",
			Content: []any{wireToolResultBlock{
				Type:      "tool_result",
				ToolUseID: output.CallID,
				Content:   output.Output,
			}},
		}}

	default:
		return nil
	}
}

func projectMessage(message rolloutMessage) []any {
	switch message.Role {
	case "user":
		text := messageText(message, "input_text")
		if text == "" || isHarnessContext(text) {
			return nil
		}
		return []any{wireMessage{
			Role:    "user",
			Content: []any{wireTextBlock{Type: "text", Text: text}},
		}}
	case "assistant":
		text := messageText(message, "output_text")
		if strings.TrimSpace(text) == "" {
			return nil
		}
		return []any{wireMessage{
			Role:    "assistant",
			Content: []any{wireTextBlock{Type: "text", Text: text}},
		}}
	default:
		return nil
	}
}

// decodeToolArguments parses the JSON-encoded arguments string into an object;
// a non-object or unparseable payload is forwarded as-is.
func decodeToolArguments(arguments string) any {
	trimmed := strings.TrimSpace(arguments)
	if trimmed == "" {
		return map[string]any{}
	}
	var value map[string]any
	if err := json.Unmarshal([]byte(trimmed), &value); err != nil {
		return trimmed
	}
	return value
}

// wireMessage is the "message" wrapper Entire's transcript compactor reads.
type wireMessage struct {
	Role    string `json:"role"`
	ID      string `json:"id,omitempty"`
	Content []any  `json:"content"`
}

type wireTextBlock struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

type wireToolUseBlock struct {
	Type  string `json:"type"`
	ID    string `json:"id,omitempty"`
	Name  string `json:"name"`
