package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

// Sarvam Code lifecycle adapter.
//
// Two sarvam-specific constraints shape this adapter:
//
//  1. Hooks fire only in interactive (TUI) sessions — a headless
//     `sarvam-code exec` run never invokes them — so RunPrompt drives the
//     TUI through tmux instead of calling exec directly.
//  2. Project config is trust-gated: a directory is trusted on first run, and
//     freshly installed hooks need a one-time /hooks review. A trivial exec
//     run records directory trust without any prompt (verified behavior), and
//     the review is automated through tmux keys the way a user does it.
const (
	sarvamTimeoutMultiplier = 2.0
	// The TUI status bar: "─ Flow · Auto ──…" (also Ask/Yolo).
	sarvamPromptPattern = `Flow · `
	// Banner the TUI shows until every installed hook is reviewed.
	sarvamReviewBanner = "hooks need review"
	// Number of hooks entire-agent-sarvam installs.
	sarvamInstalledHooks = 5
)

func init() {
	// Sarvam Code needs a logged-in CLI with network access, so the suite
	// only runs when explicitly requested.
	if os.Getenv("E2E_AGENT") != "sarvam" {
		return
	}
	Register(&Sarvam{})
	RegisterGate("sarvam", 1)
}

type Sarvam struct{}

type sarvamSession struct {
	*TmuxSession
}

func (s *sarvamSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
	return s.TmuxSession.WaitFor(pattern, time.Duration(float64(timeout)*sarvamTimeoutMultiplier))
}

func (s *Sarvam) Name() string               { return "sarvam" }
func (s *Sarvam) Binary() string             { return "sarvam-code" }
func (s *Sarvam) EntireAgent() string         { return "sarvam" }
func (s *Sarvam) PromptPattern() string      { return sarvamPromptPattern }
func (s *Sarvam) TimeoutMultiplier() float64 { return sarvamTimeoutMultiplier }
func (s *Sarvam) IsExternalAgent() bool      { return true }

func (s *Sarvam) IsTransientError(out Output, _ error) bool {
	combined := strings.ToLower(out.Stdout + out.Stderr)
	patterns := []string{
		"overloaded",
		"rate limit",
		"429",
		"500",
		"503",
		"econnreset",
		"etimedout",
		"timeout",
	}
	for _, pattern := range patterns {
		if strings.Contains(combined, pattern) {
			return true
		}
	}
	return false
}

func (s *Sarvam) Bootstrap() error {
	if _, err := exec.LookPath(s.Binary()); err != nil {
		return fmt.Errorf("%s not in PATH: %w", s.Binary(), err)
	}
	return nil
}

// trustRepo runs a throwaway headless prompt so sarvam records directory
// trust in its user config the way first-run acceptance would. Without it the
// TUI opens with a trust dialog instead of the composer.
func (s *Sarvam) trustRepo(ctx context.Context, dir string) error {
	bin, err := exec.LookPath(s.Binary())
	if err != nil {
		return fmt.Errorf("%s not in PATH: %w", s.Binary(), err)
	}
	trustCtx, cancel := context.WithTimeout(ctx, 90*time.Second)
	defer cancel()
	cmd := exec.CommandContext(trustCtx, bin, "exec", "--skip-git-repo-check", "-C", dir, "Reply with the single word: ok")
	cmd.Dir = dir
	cmd.Env = os.Environ()
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("trust run for %s failed: %w\n%s", dir, err, out)
	}
	return nil
}

func (s *Sarvam) RunPrompt(ctx context.Context, dir string, prompt string, _ ...Option) (Output, error) {
	session, err := s.StartSession(ctx, dir)
	if err != nil {
		return Output{}, err
	}
	defer func() { _ = session.Close() }()

	sess := session.(*sarvamSession)
	display := s.Binary() + " (tmux) " + fmt.Sprintf("%q", prompt)
	if _, err := sess.SendAndWait(prompt, s.PromptPattern(), 3*time.Minute); err != nil {
		return Output{Command: display, Stdout: sess.Capture()}, err
	}
	return Output{Command: display, Stdout: sess.Capture()}, nil
}

func (s *Sarvam) StartSession(ctx context.Context, dir string) (Session, error) {
	if err := s.trustRepo(ctx, dir); err != nil {
		return nil, err
	}

	name := fmt.Sprintf("sarvam-test-%d", time.Now().UnixNano())
	sess, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, s.Binary())
	if err != nil {
		return nil, err
	}
	if err := sess.SetBusyPattern(`\(esc to interrupt\)`); err != nil {
		_ = sess.Close()
		return nil, fmt.Errorf("compile sarvam busy pattern: %w", err)
	}
	if _, err := sess.WaitFor(s.PromptPattern(), 60*time.Second); err != nil {
		_ = sess.Close()
		return nil, fmt.Errorf("waiting for initial prompt: %w", err)
	}
	// Give the TUI a moment to paint any hook-review banner before deciding
	// whether the review flow is needed.
	time.Sleep(2 * time.Second)
	if strings.Contains(sess.Capture(), sarvamReviewBanner) {
		if err := reviewSarvamHooks(sess); err != nil {
			_ = sess.Close()
			return nil, err
		}
	}
	sess.stableAtSend = ""
	return &sarvamSession{TmuxSession: sess}, nil
}

// reviewSarvamHooks drives the one-time /hooks review through tmux keys:
// for each installed hook, open its row, trust it (t), enable it (space),
// and return to the table. This is the same flow a user performs by hand.
func reviewSarvamHooks(sess *TmuxSession) error {
	keys := func(keys ...string) error {
		for _, key := range keys {
			if err := sess.SendKeys(key); err != nil {
				return err
			}
			time.Sleep(400 * time.Millisecond)
		}
		return nil
	}

	if err := keys("/hooks"); err != nil {
		return err
	}
	if err := keys("Enter"); err != nil {
		return err
	}
	time.Sleep(1 * time.Second)
	for i := 0; i < sarvamInstalledHooks; i++ {
		if err := keys("Enter", "t", "Space", "Escape"); err != nil {
			return err
		}
		keys("Down")
	}
	if err := keys("Escape"); err != nil {
		return err
	}
	time.Sleep(1 * time.Second)

	if strings.Contains(sess.Capture(), sarvamReviewBanner) {
		return errors.New("sarvam hooks still need review after automated /hooks pass")
	}
	return nil
}

package sarvam

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func testEntries() []configHookEntry {
	entries := make([]configHookEntry, 0, len(hookSpecs))
	for _, spec := range hookSpecs {
		entries = append(entries, configHookEntry{
			Event:   spec.SarvamEvent,
			Command: hookCommand(spec.HookName),
		})
	}
	return entries
}

func writeConfig(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), ".sarvam", "config.toml")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	return path
}

func readConfig(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

func TestInstallHooks_FreshConfig(t *testing.T) {
	path := filepath.Join(t.TempDir(), ".sarvam", "config.toml")

	count, err := upsertHookEntries(path, testEntries(), false)
	if err != nil {
		t.Fatal(err)
	}
	if count != len(hookSpecs) {
		t.Fatalf("first install: hooks_installed = %d, want %d", count, len(hookSpecs))
	}

	content := readConfig(t, path)
	for _, spec := range hookSpecs {
		if !strings.Contains(content, "[[hooks."+spec.SarvamEvent+"]]") {
			t.Errorf("config missing [[hooks.%s]] group header", spec.SarvamEvent)
		}
		if !strings.Contains(content, "entire hooks sarvam "+spec.HookName) {
			t.Errorf("config missing command for %s", spec.HookName)
		}
	}
}

func TestInstallHooks_Idempotent(t *testing.T) {
	path := writeConfig(t, "")

	if _, err := upsertHookEntries(path, testEntries(), false); err != nil {
		t.Fatal(err)
	}
	count, err := upsertHookEntries(path, testEntries(), false)
	if err != nil {
		t.Fatal(err)
	}
	if count != 0 {
		t.Fatalf("second install: hooks_installed = %d, want 0", count)
	}
}

func TestInstallHooks_ForceReinstalls(t *testing.T) {
	path := writeConfig(t, "")

	if _, err := upsertHookEntries(path, testEntries(), false); err != nil {
		t.Fatal(err)
	}
	count, err := upsertHookEntries(path, testEntries(), true)
	if err != nil {
		t.Fatal(err)
	}
	if count != len(hookSpecs) {
		t.Fatalf("force install: hooks_installed = %d, want %d", count, len(hookSpecs))
	}
}

func TestInstallHooks_PreservesUnrelatedContent(t *testing.T) {
	path := writeConfig(t, `# my config
model = "glm-5.3"

[model.lite]
context_window = 128000

[[hooks.SessionStart]]
[[hooks.SessionStart.hooks]]
type = "command"
command = "/usr/local/bin/my-own-start-hook"
timeout = 30
`)

	if _, err := upsertHookEntries(path, testEntries(), false); err != nil {
		t.Fatal(err)
	}
	content := readConfig(t, path)

	for _, want := range []string{
		"# my config",
		`model = "glm-5.3"`,
		"[model.lite]",
		"context_window = 128000",
		`command = "/usr/local/bin/my-own-start-hook"`,
		"entire hooks sarvam session-start",
	} {
		if !strings.Contains(content, want) {
			t.Errorf("config lost unrelated content: %q missing from:\n%s", want, content)
		}
	}
}

func TestInstallHooks_RepairsParentlessHooksShape(t *testing.T) {
	// The shape the sarvam docs' SessionStart example produces: hook entries
	// with no matcher-group header, which the CLI rejects wholesale
	// ("invalid type: map, expected a sequence").
	path := writeConfig(t, `[hooks]
[[hooks.SessionStart.hooks]]
type = "command"
command = "/usr/local/bin/my-own-start-hook"
`)

	if _, err := upsertHookEntries(path, testEntries(), false); err != nil {
		t.Fatal(err)
	}
	content := readConfig(t, path)

	if !strings.Contains(content, "[[hooks.SessionStart]]\n[[hooks.SessionStart.hooks]]") {
		t.Errorf("parentless repair did not insert group header:\n%s", content)
	}
	if !strings.Contains(content, `command = "/usr/local/bin/my-own-start-hook"`) {
		t.Errorf("repair dropped the author's hook entry:\n%s", content)
	}
}

func TestInstallHooks_RejectsMapFormEvent(t *testing.T) {
	path := writeConfig(t, `[hooks.SessionStart]
`)

	if _, err := upsertHookEntries(path, testEntries(), false); err == nil {
		t.Fatal("expected an error for the table-form event header")
	}
}

func TestUninstallHooks_RemovesOnlyEntireEntries(t *testing.T) {
	path := writeConfig(t, `model = "glm-5.3"

[[hooks.SessionStart]]
[[hooks.SessionStart.hooks]]
type = "command"
command = "/usr/local/bin/my-own-start-hook"
`)

	if _, err := upsertHookEntries(path, testEntries(), false); err != nil {
		t.Fatal(err)
	}
	if err := removeHookEntries(path, hookSpecs); err != nil {
		t.Fatal(err)
	}

	content := readConfig(t, path)
	if strings.Contains(content, "entire hooks sarvam") {
		t.Errorf("uninstall left entire entries behind:\n%s", content)
	}
	for _, want := range []string{
		`model = "glm-5.3"`,
		`command = "/usr/local/bin/my-own-start-hook"`,
		"[[hooks.SessionStart]]",
	} {
		if !strings.Contains(content, want) {
			t.Errorf("uninstall removed foreign content %q:\n%s", want, content)
		}
	}
}

func TestUninstallHooks_RemovesEmptyManagedGroups(t *testing.T) {
	path := writeConfig(t, "")

	if _, err := upsertHookEntries(path, testEntries(), false); err != nil {
		t.Fatal(err)
	}
	if err := removeHookEntries(path, hookSpecs); err != nil {
		t.Fatal(err)
	}

	content := readConfig(t, path)
	if strings.Contains(content, "hooks.") {
		t.Errorf("uninstall left managed hook scaffolding behind:\n%s", content)
	}
}

func TestHookEntryInstalled(t *testing.T) {
	path := writeConfig(t, "")
	spec := hookSpecs[0]
	command := hookCommand(spec.HookName)

	if hookEntryInstalled(path, spec.SarvamEvent, spec.EntryName, command) {
		t.Fatal("hooks must not be installed before install-hooks")
	}
	if _, err := upsertHookEntries(path, testEntries(), false); err != nil {
		t.Fatal(err)
	}
	if !hookEntryInstalled(path, spec.SarvamEvent, spec.EntryName, command) {
		t.Fatal("hooks must be installed after install-hooks")
	}
}

func TestParseKeyValue_QuotedStrings(t *testing.T) {
	cases := []struct {
		line    string
		key     string
		value   string
	}{
		{`command = "sh -c 'echo hi'"`, "command", `sh -c 'echo hi'`},
		{`command = 'sh -c "echo hi"'`, "command", `sh -c "echo hi"`},
		{"command = \"a\\\"b\"", "command", `a"b`},
		{`timeout = 30`, "timeout", "30"},
		{`# comment`, "", ""},
	}
	for _, tc := range cases {
		key, value, ok := parseKeyValue(tc.line)
		if key != tc.key || value != tc.value {
			t.Errorf("parseKeyValue(%q) = (%q, %q, %v), want (%q, %q)", tc.line, key, value, ok, tc.key, tc.value)
		}
	}
}

package sarvam

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
)

// capturedPayload returns a hook payload captured from a live sarvam-code
// session (testdata/hook-payloads, gathered 2026-11-16 against 0.58.0).
func capturedPayload(t *testing.T, event string) []byte {
	t.Helper()
	path := filepath.Join("..", "..", "testdata", "hook-payloads", event+".json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read captured payload %s: %v (rerun scripts/verify-sarvam.sh to regenerate)", event, err)
	}
	return data
}

func TestParseHook_NativePayloads(t *testing.T) {
	agent := New()
	cases := []struct {
		event      string
		wantType   int
		wantPrompt string
		wantResp   string
	}{
		{"SessionStart", 1, "", ""},
		{"UserPromptSubmit", 2, "Use the shell to run the command: echo hi > hi.txt and then reply done", ""},
		{"Stop", 3, "", "done"},
		{"PreCompact", 4, "", ""},
		{"PostCompact", 4, "", ""},
	}
	for _, tc := range cases {
		t.Run(tc.event, func(t *testing.T) {
			event, err := agent.ParseHook(tc.event, capturedPayload(t, tc.event))
			if err != nil {
				t.Fatal(err)
			}
			if event == nil {
				t.Fatal("expected a lifecycle event, got nil")
			}
			if event.Type != tc.wantType {
				t.Errorf("type = %d, want %d", event.Type, tc.wantType)
			}
			if event.SessionID != "01a1e2d3-8a2b-7dc2-b125-885a43ce43f5" {
				t.Errorf("session_id = %q", event.SessionID)
			}
			if event.SessionRef == "" || filepath.Base(event.SessionRef) != "rollout-2026-11-16T06-27-56-01a1e2d3-8a2b-7dc2-b125-885a43ce43f5.jsonl" {
				t.Errorf("session_ref = %q, want the native rollout path", event.SessionRef)
			}
			if event.Model != "glm-5.3" {
				t.Errorf("model = %q", event.Model)
			}
			if event.Timestamp == "" {
				t.Error("timestamp must be filled in (sarvam payloads carry none)")
			}
			if _, err := time.Parse(time.RFC3339, event.Timestamp); err != nil {
				t.Errorf("timestamp %q is not RFC3339: %v", event.Timestamp, err)
			}
			if tc.wantPrompt != "" && event.Prompt != tc.wantPrompt {
				t.Errorf("prompt = %q, want %q", event.Prompt, tc.wantPrompt)
			}
			if tc.wantResp != "" && event.ResponseMessage != tc.wantResp {
				t.Errorf("response_message = %q, want %q", event.ResponseMessage, tc.wantResp)
			}
		})
	}
}

func TestParseHook_ToolAndPermissionEventsAreNull(t *testing.T) {
	agent := New()
	for _, event := range []string{"PreToolUse", "PostToolUse", "PermissionRequest"} {
		t.Run(event, func(t *testing.T) {
			eventJSON, err := agent.ParseHook(event, capturedPayload(t, event))
			if err != nil {
				t.Fatal(err)
			}
			if eventJSON != nil {
				t.Fatalf("expected nil event for %s, got %+v", event, eventJSON)
			}
		})
	}
}

func TestParseHook_ProtocolHookInputShape(t *testing.T) {
	agent := New()
	input, err := json.Marshal(protocol.HookInputJSON{
		HookType:   "user-prompt-submit",
		SessionID:  "test-session-abc",
		SessionRef: "/tmp/transcript.jsonl",
		Timestamp:  "2026-01-01T00:00:00Z",
		UserPrompt: "test prompt",
	})
	if err != nil {
		t.Fatal(err)
	}

	event, err := agent.ParseHook("user-prompt-submit", input)
	if err != nil {
		t.Fatal(err)
	}
	if event == nil || event.Type != 2 {
		t.Fatalf("expected TurnStart (type 2), got %+v", event)
	}
	if event.SessionID != "test-session-abc" {
		t.Errorf("session_id = %q", event.SessionID)
	}
	if event.SessionRef != "/tmp/transcript.jsonl" {
		t.Errorf("session_ref = %q", event.SessionRef)
	}
	if event.Prompt != "test prompt" {
		t.Errorf("prompt = %q", event.Prompt)
	}
}

func TestParseHook_EmptyAndInvalidInput(t *testing.T) {
	agent := New()

	event, err := agent.ParseHook("session-start", nil)
	if err != nil || event != nil {
		t.Fatalf("empty input: got (%+v, %v), want (nil, nil)", event, err)
	}

	if _, err := agent.ParseHook("session-start", []byte(`{"session_id":`)); err == nil {
		t.Fatal("invalid JSON must error")
	}
}

