func dropEntireEntries(blocks []tomlBlock) []tomlBlock {
	out := make([]tomlBlock, 0, len(blocks))
	for _, block := range blocks {
		event, kind := headerEvent(block.header)
		if event != "" && kind == kindHooks && isEntireEntry(block) {
			continue
		}
		out = append(out, block)
	}
	return out
}

// legacyManagedEvents are events an earlier release of this adapter
// installed — PreCompact, dropped once compaction was reported once, from
// PostCompact. They are absent from hookSpecs, but uninstall and force
// installs must still clean the empty group headers those installs leave
// behind: their owned entries carry our command marker and are already
// removed, so an empty group is always our residue.
var legacyManagedEvents = []string{"PreCompact"}

// isCleanedEvent reports whether an event's empty group headers are ours to
// remove on uninstall and force installs: the events we install today, plus
// the legacy events an older release installed.
func isCleanedEvent(event string) bool {
	if isManagedEvent(event) {
		return true
	}
	for _, legacy := range legacyManagedEvents {
		if legacy == event {
			return true
		}
	}
	return false
}

// dropEmptyManagedGroups removes [[hooks.<Event>]] group headers we own that
// no longer parent any hook entry: an empty group is kept only when a
// same-event [[hooks.<Event>.hooks]] entry immediately follows it — the
// parent relationship TOML array-of-tables gives an entry. A group that
// still carries content (a matcher) always stays, and events we never
// installed are never touched.
func dropEmptyManagedGroups(blocks []tomlBlock) []tomlBlock {
	out := make([]tomlBlock, 0, len(blocks))
	for i, block := range blocks {
		event, kind := headerEvent(block.header)
		if event != "" && kind == "group" && isCleanedEvent(event) &&
			len(block.body) == 0 && !followedBySameEventEntry(blocks, i) {
			continue
		}
		out = append(out, block)
	}
	return out
}

